  "route": "도쿄역에서 도호쿠 신칸센을 타면 기타카미역까지 약 2시간 40~50분, 센다이에서 약 45분, 모리오카에서는 15분이면 닿는다. 이와테현 한가운데 놓인 교통 요충지라 하나마키·오슈·히라이즈미 어디로든 재빨리 빠질 수 있고, 역에서 서쪽으로 JR 기타카미선을 타면 아키타현 요코테까지도 이어진다. 다만 게토 온천과 게토고원 쪽 산은 버스 편이 성기니, 산까지 들어갈 생각이면 렌터카가 마음 편하다.",
  "sep": "4월 중순~하순. 기타카미강 기슭을 따라 2km 남짓 이어지는 텐쇼치 벚꽃 터널이 이 도시의 이유 그 자체다. 100년 넘은 왕벚나무들이 길 위로 가지를 맞대 하늘을 가리고, 강 위에는 잉어 깃발이 떠 있고, 저녁이면 야간 조명이 들어온다. 8월 초라면 이야기가 달라진다. 8월 7~9일 사흘간 열리는 미치노쿠 예능축제에 100개가 넘는 단체가 몰려와 오니켄바이를 추고, 마지막 밤엔 등롱 흘려보내기와 불꽃놀이로 끝난다. 겨울은 겨울대로, 게토고원의 눈이 도호쿠에서 손꼽히게 깊다.",
