  "route": "히로사키역에서 고난철도 고난선을 타면 약 30분 만에 구로이시역이다. 두 량짜리 지방철도가 사과밭 사이를 느리게 지나가는 구간이라 이동 자체가 이미 여행이 된다. 아오모리 시내에서는 고난버스로 약 1시간, 차로 가면 도호쿠 자동차도 구로이시IC에서 시내까지 10분 남짓 — 산속 온천까지 들어갈 생각이면 렌터카가 훨씬 편하다.",
