    "desc": "'코미세'는 상점 앞에 기둥을 세우고 처마를 길게 빼 만든 목조 통로다. 햇볕과 눈보라로부터 손님을 지키려고 상인들이 각자 자기 부지에 만든 것이 이어져 하나의 아케이드가 됐다. 에도 전기 모습 그대로 이만큼 한 거리에 남아 있는 예는 전국적으로도 드물다고 하며, 기둥 사이로 새어드는 빛과 발밑 나무 바닥 소리만으로도 시대가 한 겹 벗겨진 느낌이 든다.",
